import sys

def find_path(n, types, tracks):
    # Create a dictionary to store the reverse tracks
    reverse_tracks = {}
    for i in range(n):
        if tracks[i] != 0:
            if tracks[i] - 1 not in reverse_tracks:
                reverse_tracks[tracks[i] - 1] = []
            reverse_tracks[tracks[i] - 1].append(i)

    # Initialize the maximum path length and the best path
    max_length = 0
    best_path = []

    # Iterate over each hotel to find the longest path ending at that hotel
    for i in range(n):
        if types[i] == 1:
            current_length = 0
            current_path = []
            visited = set()
            stack = [i]

            while stack:
                node = stack.pop()
                if node not in visited:
                    visited.add(node)
                    current_length += 1
                    current_path.append(node + 1)
                    if node in reverse_tracks:
                        for neighbor in reverse_tracks[node]:
